"use client";

import { DetailDrawer } from "@/components/application/animations/expanded/controls/detail-drawer";

export default function Example() {
  return (
    <DetailDrawer
      title={"Tempo Runner II"}
      subtitle={"Move faster. Feel stronger."}
      image={{
        "src": "/assets/zeus/product_shoe_06.jpg",
        "alt": "Tempo Runner II performance shoe"
      }}
      paragraphs={[
        "A product deserves room for the details. This sample drawer pairs a large image with an introduction, a few supporting paragraphs, and an action you can connect to your own application.",
        "The image moves back as the panel enters, preserving the relationship between the overview and the information you just opened. On a smaller screen, the drawer uses more of the available width and keeps its content scrollable.",
        "Replace these paragraphs with the information your visitors need. The component accepts your title, subtitle, image, and content, along with an action callback and controlled open state."
      ]}
      actionLabel={"Add to cart"}
      duration={1}
    />
  );
}

