"use client";
import { useId, useRef, type ReactNode } from "react";
import { motion } from "motion/react";
import {
  ControlStyles,
  ControlTextLines,
  controlVariables,
  useControlDialog,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface DetailDrawerProps extends ControlAppearance {
  title: string;
  subtitle?: string;
  image: { src: string; alt: string };
  paragraphs?: readonly string[];
  children?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  actionLabel?: string;
  onAction?: () => void;
  closeLabel?: string;
  /** Delay between naturally wrapped lines, in seconds. */
  stagger?: number;
}
export function DetailDrawer({
  title,
  subtitle,
  image,
  paragraphs = [],
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  actionLabel,
  onAction,
  closeLabel = "Close details",
  stagger = 0.045,
  ...appearance
}: DetailDrawerProps) {
  const [isOpen, setOpen] = useControlValue(open, defaultOpen, onOpenChange);
  const initiallyOpen = useRef(isOpen);
  const transition = useControlTransition(appearance.duration ?? 1);
  const dialog = useControlDialog(isOpen, setOpen, appearance.duration ?? 1);
  const id = useId();
  return (
    <>
      <ControlStyles />
      <div
        className={`z-mc z-mc-drawer ${appearance.className ?? ""}`}
        style={controlVariables({ background: "#e8e8e8", color: "#111111", ...appearance })}
      >
        <button
          type="button"
          className="z-mc-drawer-hero"
          aria-label={`View ${title} details`}
          aria-haspopup="dialog"
          aria-expanded={isOpen}
          onClick={() => setOpen(true)}
        >
          <motion.img
            src={image.src}
            alt={image.alt}
            initial={false}
            animate={{
              scale: isOpen ? 1.22 : 1,
              x: isOpen ? "-15%" : "0%",
              filter: isOpen ? "brightness(.3) blur(6px)" : "brightness(.8) blur(0px)",
            }}
            transition={transition}
          />
          <motion.span
            className="z-mc-drawer-hero-label"
            animate={{ opacity: isOpen ? 0 : 1 }}
            transition={transition}
          >
            <strong>{title}</strong>
            <i aria-hidden="true">↗</i>
          </motion.span>
        </button>
        <dialog
          open={initiallyOpen.current || undefined}
          ref={dialog}
          className="z-mc z-mc-native-dialog"
          aria-labelledby={`${id}-title`}
        >
          <motion.div
            className="z-mc-dialog-shade"
            aria-hidden="true"
            initial={false}
            animate={{ opacity: isOpen ? 0.6 : 0 }}
            transition={transition}
            onClick={() => setOpen(false)}
          />
          <motion.section
            className="z-mc-drawer-panel"
            initial={false}
            animate={{ x: isOpen ? "0%" : "100%" }}
            transition={transition}
          >
            <button
              type="button"
              autoFocus
              className="z-mc-close"
              aria-label={closeLabel}
              onClick={() => setOpen(false)}
            >
              ×
            </button>
            <motion.div
              initial={false}
              animate={{ opacity: isOpen ? 1 : 0, y: isOpen ? 0 : 24 }}
              transition={{
                ...transition,
                delay: isOpen ? Number(transition.duration ?? 0) * 0.18 : 0,
              }}
            >
              <h2 id={`${id}-title`}>{title}</h2>
              {subtitle && <h3>{subtitle}</h3>}
            </motion.div>
            {paragraphs.map((paragraph, index) => (
              <ControlTextLines
                key={index}
                text={paragraph}
                open={isOpen}
                duration={appearance.duration ?? 1}
                stagger={stagger}
                delay={Number(transition.duration ?? 0) * (0.24 + index * 0.06)}
              />
            ))}
            {children}
            {actionLabel && (
              <button type="button" className="z-mc-product-action" onClick={onAction}>
                {actionLabel}
              </button>
            )}
          </motion.section>
        </dialog>
      </div>
    </>
  );
}
